export async function callTool(name, args = {}) {
  if (name !== 'download_asset') {
    const error = new Error('Unknown tool: ' + name);
    error.code = -32601;
    throw error;
  }
  // Validate arguments is an object
  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
    const error = new Error('Invalid arguments: expected an object');
    error.code = -32602;
    throw error;
  }
  // Reject extra fields
  const allowed = new Set(['asset_id']);
  for (const key of Object.keys(args)) {
    if (!allowed.has(key)) {
      const error = new Error('Unexpected field: ' + key);
      error.code = -32602;
      throw error;
    }
  }
  // Validate asset_id
  if (!('asset_id' in args)) {
    const error = new Error('Missing required argument: asset_id');
    error.code = -32602;
    throw error;
  }
  const { asset_id } = args;
  if (typeof asset_id !== 'string') {
    const error = new Error('Invalid argument: asset_id must be a string');
    error.code = -32602;
    throw error;
  }
  // Reject unknown assets
  const asset = ASSETS[asset_id];
  if (!asset) {
    const error = new Error('Unknown asset: ' + asset_id);
    error.code = -32602;
    throw error;
  }
  return {
    content: [
      {
        type: 'resource',
        resource: {
          uri: `asset://${asset_id}`,
          mimeType: asset.mimeType,
          blob: asset.blob
        }
      }
    ]
  };
}
